CREATE DATABASE IF NOT EXISTS campusloop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campusloop;
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, college_id VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, department VARCHAR(100) DEFAULT '', year_of_study VARCHAR(30) DEFAULT '', bio TEXT, is_admin BOOLEAN DEFAULT FALSE, suspended BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS posts (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, kind ENUM('market','task','delivery') NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, category VARCHAR(80) DEFAULT 'Other', price DECIMAL(10,2) NOT NULL, location VARCHAR(180) NOT NULL, destination VARCHAR(180) DEFAULT '', status VARCHAR(30) DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS post_inventory (post_id BIGINT PRIMARY KEY, quantity INT NOT NULL DEFAULT 1, FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
INSERT IGNORE INTO post_inventory(post_id,quantity) SELECT id,1 FROM posts WHERE kind='market';
CREATE TABLE IF NOT EXISTS blogs (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_blogs_created (created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS saved_posts (user_id BIGINT NOT NULL, post_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,post_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS post_attachments (id BIGINT AUTO_INCREMENT PRIMARY KEY, post_id BIGINT NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(80) NOT NULL UNIQUE, content_type VARCHAR(120) NOT NULL, file_size BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_post_attachments_post (post_id), FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS deals (id BIGINT AUTO_INCREMENT PRIMARY KEY, post_id BIGINT NOT NULL, owner_id BIGINT NOT NULL, worker_id BIGINT NOT NULL, status VARCHAR(40) DEFAULT 'Requested', otp VARCHAR(6), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(post_id,worker_id), FOREIGN KEY(post_id) REFERENCES posts(id), FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(worker_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS deal_quantities (deal_id BIGINT PRIMARY KEY, quantity INT NOT NULL DEFAULT 1, FOREIGN KEY(deal_id) REFERENCES deals(id) ON DELETE CASCADE);
INSERT IGNORE INTO deal_quantities(deal_id,quantity) SELECT id,1 FROM deals;
CREATE TABLE IF NOT EXISTS messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, deal_id BIGINT NOT NULL, sender_id BIGINT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(deal_id) REFERENCES deals(id), FOREIGN KEY(sender_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS direct_messages (id BIGINT AUTO_INCREMENT PRIMARY KEY, sender_id BIGINT NOT NULL, recipient_id BIGINT NOT NULL, body TEXT NOT NULL, read_at TIMESTAMP NULL DEFAULT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_direct_messages_conversation (sender_id,recipient_id,created_at), INDEX idx_direct_messages_unread (recipient_id,sender_id,read_at), FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, deal_id BIGINT NOT NULL, author_id BIGINT NOT NULL, target_id BIGINT NOT NULL, rating INT NOT NULL, body TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(deal_id,author_id), FOREIGN KEY(deal_id) REFERENCES deals(id), FOREIGN KEY(author_id) REFERENCES users(id), FOREIGN KEY(target_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS product_reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, post_id BIGINT NOT NULL, deal_id BIGINT NOT NULL, reviewer_id BIGINT NOT NULL, rating INT NOT NULL, body TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(deal_id), UNIQUE(post_id,reviewer_id), INDEX idx_product_reviews_post (post_id), FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE CASCADE, FOREIGN KEY(deal_id) REFERENCES deals(id) ON DELETE CASCADE, FOREIGN KEY(reviewer_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reports (id BIGINT AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT NOT NULL, post_id BIGINT, reason TEXT NOT NULL, status VARCHAR(30) DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reporter_id) REFERENCES users(id), FOREIGN KEY(post_id) REFERENCES posts(id));
CREATE TABLE IF NOT EXISTS safety_reports (id BIGINT AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT NOT NULL, post_id BIGINT NULL, reported_user_id BIGINT NULL, category VARCHAR(60) NOT NULL, details TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_safety_reports_status_created (status,created_at), FOREIGN KEY(reporter_id) REFERENCES users(id), FOREIGN KEY(post_id) REFERENCES posts(id) ON DELETE SET NULL, FOREIGN KEY(reported_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS disputes (id BIGINT AUTO_INCREMENT PRIMARY KEY, deal_id BIGINT NOT NULL, opened_by BIGINT NOT NULL, details TEXT NOT NULL, deal_status_before VARCHAR(40) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Open', resolution VARCHAR(1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, resolved_at TIMESTAMP NULL DEFAULT NULL, INDEX idx_disputes_status_created (status,created_at), FOREIGN KEY(deal_id) REFERENCES deals(id), FOREIGN KEY(opened_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, body VARCHAR(500) NOT NULL, is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notification_targets (notification_id BIGINT PRIMARY KEY, event_type VARCHAR(20) NOT NULL, event_id BIGINT NULL, FOREIGN KEY(notification_id) REFERENCES notifications(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS support_tickets (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, subject VARCHAR(160) NOT NULL, details TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_support_tickets_status_created (status,created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lost_found_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, kind ENUM('Lost','Found') NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, location VARCHAR(180) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_lost_found_status_created (status,created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS campus_announcements (id BIGINT AUTO_INCREMENT PRIMARY KEY, author_id BIGINT NOT NULL, title VARCHAR(180) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_announcements_created (created_at), FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS delivery_locations (deal_id BIGINT PRIMARY KEY, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(deal_id) REFERENCES deals(id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS mobile_tokens (token VARCHAR(100) PRIMARY KEY, user_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
